import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"Avec un agent","description":"","frontmatter":{"title":"Avec un agent"},"headers":[],"relativePath":"agent/index.md","filePath":"agent/index.md"}'),o={name:"agent/index.md"};function i(s,e,u,l,d,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="avec-un-agent" tabindex="-1">Avec un agent <a class="header-anchor" href="#avec-un-agent" aria-label="Permalink to &quot;Avec un agent&quot;">​</a></h1><p>Votre agent IA utilise Daimon par ses outils MCP : il regarde l&#39;écran, lit l&#39;interface, agit à votre place et vous montre ce qu&#39;il fait. Vous décidez, l&#39;agent exécute, et le plafond que vous fixez borne tout ce qu&#39;il peut faire.</p><p>Vous parlez à votre agent en langage naturel. Chaque page de ce guide part de ce que vous lui demandez, puis dit ce qu&#39;il fait, ce que vous obtenez, et ce qui se passe quand un appel est refusé.</p><h2 id="compatibilite" tabindex="-1">Compatibilité <a class="header-anchor" href="#compatibilite" aria-label="Permalink to &quot;Compatibilité&quot;">​</a></h2><p>Daimon ne cible pas un agent en particulier : tout client MCP capable de lancer un serveur en stdio peut l&#39;utiliser. Les agents qui s&#39;appuient sur des modèles de pointe sont les plus à même d&#39;enchaîner perception et action de façon fiable. La liste des clients que Daimon sait configurer est dans <a href="/Daimon/guide/clients-mcp.html">Clients IA</a>.</p><h2 id="travailler-au-mieux" tabindex="-1">Travailler au mieux <a class="header-anchor" href="#travailler-au-mieux" aria-label="Permalink to &quot;Travailler au mieux&quot;">​</a></h2><p>Contrairement à un outil lié à un projet, Daimon n&#39;a pas de dossier de travail : il agit sur <strong>votre machine</strong>, quel que soit l&#39;endroit où la session de l&#39;agent est ouverte. Ce qui compte :</p><ul><li><strong>Daimon est enregistré dans votre agent</strong> et l&#39;agent a été redémarré depuis (voir ci-dessous) ;</li><li><strong>les autorisations système sont accordées</strong> : <a href="/Daimon/guide/autorisations.html">Autorisations</a> ;</li><li><strong>le plafond est à la hauteur de la tâche</strong> : à L0 (le réglage par défaut), l&#39;agent peut regarder, pas agir. Voir <a href="/Daimon/agent/agir.html">Agir</a> ;</li><li><strong>le panneau Daimon est à portée de clic</strong>, et <strong>Présence à l&#39;écran</strong> est activée si vous voulez voir ce que fait l&#39;agent : voir <a href="/Daimon/agent/montrer.html">Montrer ce qui se passe</a>.</li></ul><p>Puis parlez-lui : « Vérifie que Daimon est prêt » ou « Regarde mon écran et dis-moi quelle fenêtre est au premier plan ».</p><h2 id="connecter-un-agent" tabindex="-1">Connecter un agent <a class="header-anchor" href="#connecter-un-agent" aria-label="Permalink to &quot;Connecter un agent&quot;">​</a></h2><p>Trois voies, qui font le même travail, détaillées dans <a href="/Daimon/guide/clients-mcp.html">Clients IA</a> :</p><ul><li>le parcours d&#39;installation, puis le panneau, avec un interrupteur par client ;</li><li>un terminal : <code>Daimon install</code> enregistre Daimon dans chaque client détecté ;</li><li>pour un client inconnu, une déclaration stdio dont la commande est le binaire de Daimon et l&#39;argument <code>serve</code>.</li></ul><p>Après un enregistrement, <strong>redémarrez votre agent</strong> pour qu&#39;il voie les outils.</p><h2 id="vous-gardez-la-main" tabindex="-1">Vous gardez la main <a class="header-anchor" href="#vous-gardez-la-main" aria-label="Permalink to &quot;Vous gardez la main&quot;">​</a></h2><ul><li><strong>Le plafond.</strong> Chaque action des Mains a un niveau (L1 à L4). L&#39;agent peut lire le plafond avec <code>main_ceiling</code>, <strong>jamais le relever</strong>.</li><li><strong>La confirmation.</strong> Jusqu&#39;à L3, une action que Daimon juge irréversible s&#39;arrête sur une boîte de confirmation, qui refuse d&#39;elle-même au bout de 30 secondes.</li><li><strong>L4 est votre décision.</strong> Il demande votre consentement explicite, depuis le panneau ou le terminal. Aucun outil ne permet à l&#39;agent de l&#39;engager.</li><li><strong>Vos exclusions.</strong> Les applications et zones que vous protégez sont censurées ou refusées : <a href="/Daimon/guide/plafond-et-exclusions.html">Plafond et exclusions</a>.</li><li><strong>L&#39;audit.</strong> Chaque action est consignée avec l&#39;intention que l&#39;agent a déclarée.</li></ul><h2 id="quand-un-appel-est-refuse" tabindex="-1">Quand un appel est refusé <a class="header-anchor" href="#quand-un-appel-est-refuse" aria-label="Permalink to &quot;Quand un appel est refusé&quot;">​</a></h2><p>Le refus dit toujours pourquoi, sous une forme que votre agent comprend directement :</p><table tabindex="0"><thead><tr><th>Forme</th><th>Sens</th></tr></thead><tbody><tr><td><code>{&quot;status&quot;: &quot;refused&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>Une action des Mains est refusée : plafond, garde, confirmation non obtenue</td></tr><tr><td><code>{&quot;status&quot;: &quot;error&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>Une action des Mains a échoué à s&#39;exécuter</td></tr><tr><td><code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;…&quot;}</code></td><td>Une erreur de préparation ou de perception : argument invalide, autorisation manquante, application protégée</td></tr></tbody></table><p>Chaque page de parcours liste les refus réels de ses outils. En cas de doute, l&#39;agent appelle <a href="/Daimon/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>.</p><h2 id="les-parcours" tabindex="-1">Les parcours <a class="header-anchor" href="#les-parcours" aria-label="Permalink to &quot;Les parcours&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Pour</th></tr></thead><tbody><tr><td><a href="/Daimon/agent/demarrer.html">Démarrer</a></td><td>Vérifier que Daimon est prêt avant la première tâche</td></tr><tr><td><a href="/Daimon/agent/regarder.html">Regarder l&#39;écran</a></td><td>Capturer un écran, localiser un texte, convertir des coordonnées</td></tr><tr><td><a href="/Daimon/agent/lire-interface.html">Lire une interface</a></td><td>Obtenir les éléments d&#39;une fenêtre sans passer par l&#39;image</td></tr><tr><td><a href="/Daimon/agent/agir.html">Agir</a></td><td>Cliquer, saisir, appuyer, glisser, sous le plafond que vous fixez</td></tr><tr><td><a href="/Daimon/agent/montrer.html">Montrer ce qui se passe</a></td><td>Voir à l&#39;écran ce que fait l&#39;agent</td></tr><tr><td><a href="/Daimon/agent/deleguer.html">Déléguer à un sous-agent</a></td><td>Confier un enchaînement d&#39;actions à un autre agent</td></tr><tr><td><a href="/Daimon/agent/diagnostiquer.html">Quand ça ne marche pas</a></td><td>Trouver la cause avant de conclure à une panne</td></tr></tbody></table><h2 id="reference" tabindex="-1">Référence <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Référence&quot;">​</a></h2><p>Chaque outil, ses paramètres et son niveau : <a href="/Daimon/reference/">Référence des outils</a>.</p>',23)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
